// Shared bits of the site footer (Cupertino run 3, Nov 2 2026 · DESIGN-SYSTEM.md "Footer"; R46).
// The footer's inside is generated by tools/build-footer.js between these markers, which sit INSIDE <footer>, so every
// generator that copies a shell page's `<footer>…</footer>` (card pages, card template, auctions, deals, grade premiums,
// the Topps page builder) copies the generated block whole. Whole-page writers that used to hard-code a footer call
// carryFooter() so a re-run keeps the generated footer instead of putting the old one back.
import { existsSync, readFileSync } from 'node:fs';

export const FOOTER_START = '<!-- FOOTER:START';
export const FOOTER_END = '<!-- FOOTER:END -->';
export const FOOTER_RE = /<footer>\s*<!-- FOOTER:START[\s\S]*?<!-- FOOTER:END -->\s*<\/footer>/;

// The generated <footer>…</footer> of a page already on disk, or `fallback` (the generator's own old footer, or '').
export function carryFooter(file, fallback = '') {
  try {
    if (existsSync(file)) {
      const m = readFileSync(file, 'utf8').match(FOOTER_RE);
      if (m) return m[0];
    }
  } catch (e) { /* fall through */ }
  return fallback;
}

// For whole-page writers with no footer of their own (class ladder, checklist worksheets): put the page's generated
// footer back before </body> on every rebuild. No generated footer on disk yet → the page is returned unchanged.
export function keepFooter(html, file) {
  const f = carryFooter(file);
  if (!f) return html;
  if (/<footer\b/.test(html)) return html.replace(/<footer\b[^>]*>[\s\S]*?<\/footer>/, () => f);
  const bi = html.lastIndexOf('</body>');
  return bi < 0 ? html : html.slice(0, bi) + f + '\n' + html.slice(bi);
}
